pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint b0 = address(c).balance;
        uint256 d0;
        try c.depositsCount() returns (uint256 __r) { d0 = __r; } catch { return; }
        bool reverted;
        try c.sendMoney(address(this), amount, "") { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && address(c).balance == b0 && c.depositsCount() == d0);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable { revert(); }
}
